[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ClipCast — One video is worth a thousand words</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --primary: #1868DB;
      --primary-dark: #1351a8;
      --accent: #FF613D;
      --text: #292A2E;
      --text-light: #6B7280;
      --bg: #FFFFFF;
      --bg-secondary: #F9FAFB;
      --bg-alt: #F3F4F6;
      --border: #E5E7EB;
      --purple: #7C3AED;
      --purple-light: #8B5CF6;
      --radius: 12px;
      --radius-sm: 8px;
      --shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
    }
    body { font-family: 'Plus Jakarta Sans', sans-serif; color: var(--text); background: var(--bg); line-height: 1.6; }
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    a { color: var(--primary); text-decoration: none; transition: color 0.2s; }
    a:hover { color: var(--primary-dark); }

    /* Navigation */
    .nav { position: sticky; top: 0; background: rgba(255,255,255,0.95); backdrop-filter: blur(8px); border-bottom: 1px solid var(--border); z-index: 100; }
    .nav-inner { display: flex; align-items: center; justify-content: space-between; padding: 16px 24px; max-width: 1200px; margin: 0 auto; }
    .nav-logo { font-weight: 800; font-size: 24px; color: var(--primary); display: flex; align-items: center; gap: 8px; }
    .nav-logo svg { width: 32px; height: 32px; }
    .nav-links { display: flex; align-items: center; gap: 32px; }
    .nav-link { font-weight: 500; color: var(--text); font-size: 15px; }
    .nav-link:hover { color: var(--primary); }
    .nav-actions { display: flex; align-items: center; gap: 12px; }
    .btn { display: inline-flex; align-items: center; justify-content: center; padding: 10px 20px; border-radius: var(--radius-sm); font-weight: 600; font-size: 15px; cursor: pointer; transition: all 0.2s; border: none; }
    .btn-primary { background: var(--primary); color: white; }
    .btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: var(--shadow); }
    .btn-secondary { background: white; color: var(--text); border: 1px solid var(--border); }
    .btn-secondary:hover { border-color: var(--primary); color: var(--primary); }
    .btn-accent { background: var(--accent); color: white; }
    .btn-accent:hover { background: #e5552f; transform: translateY(-1px); }
    .btn-lg { padding: 14px 28px; font-size: 16px; }
    .btn-sm { padding: 8px 16px; font-size: 14px; }

    /* Hero */
    .hero { padding: 80px 0 60px; text-align: center; background: linear-gradient(180deg, #EFF6FF 0%, var(--bg) 100%); }
    .hero-badge { display: inline-flex; align-items: center; gap: 8px; background: linear-gradient(135deg, var(--purple) 0%, var(--purple-light) 100%); color: white; padding: 6px 16px; border-radius: 50px; font-size: 13px; font-weight: 600; margin-bottom: 24px; }
    .hero h1 { font-size: clamp(40px, 6vw, 64px); font-weight: 800; line-height: 1.1; margin-bottom: 20px; background: linear-gradient(135deg, var(--text) 0%, #4B5563 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
    .hero p { font-size: 20px; color: var(--text-light); max-width: 600px; margin: 0 auto 32px; }
    .hero-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
    .hero-image { margin-top: 60px; border-radius: var(--radius); box-shadow: var(--shadow-lg); overflow: hidden; max-width: 900px; margin-left: auto; margin-right: auto; }

    /* Logo Bar */
    .logo-bar { padding: 40px 0; background: var(--bg-secondary); text-align: center; }
    .logo-bar p { color: var(--text-light); font-size: 14px; margin-bottom: 20px; }
    .logos { display: flex; align-items: center; justify-content: center; gap: 40px; flex-wrap: wrap; }
    .logos span { font-size: 20px; color: var(--text-light); font-weight: 600; opacity: 0.7; }

    /* Sections */
    .section { padding: 80px 0; }
    .section-alt { background: var(--bg-alt); }
    .section-header { text-align: center; max-width: 700px; margin: 0 auto 48px; }
    .section-header h2 { font-size: 36px; font-weight: 700; margin-bottom: 16px; }
    .section-header p { font-size: 18px; color: var(--text-light); }
    .section-label { display: inline-block; background: linear-gradient(135deg, rgba(124,58,237,0.1) 0%, rgba(139,92,246,0.1) 100%); color: var(--purple); padding: 4px 12px; border-radius: 50px; font-size: 13px; font-weight: 600; margin-bottom: 12px; }
    .section-label.new { background: var(--accent); color: white; }

    /* Feature Highlight */
    .feature-highlight { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
    .feature-highlight-content h2 { font-size: 32px; font-weight: 700; margin-bottom: 16px; }
    .feature-highlight-content p { color: var(--text-light); font-size: 17px; margin-bottom: 24px; }
    .feature-highlight-visual { background: linear-gradient(135deg, #EEF2FF 0%, #E0E7FF 100%); border-radius: var(--radius); padding: 40px; min-height: 300px; display: flex; align-items: center; justify-content: center; }

    /* Screen Recorder */
    .screen-recorder { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
    .screen-recorder-visual { background: linear-gradient(135deg, #1868DB 0%, #7C3AED 100%); border-radius: var(--radius); padding: 60px; min-height: 300px; display: flex; align-items: center; justify-content: center; color: white; font-size: 48px; }
    .screen-recorder h2 { font-size: 32px; font-weight: 700; margin-bottom: 16px; }
    .screen-recorder p { color: var(--text-light); font-size: 17px; margin-bottom: 24px; }
    .feature-list { list-style: none; }
    .feature-list li { padding: 8px 0; font-size: 16px; display: flex; align-items: center; gap: 12px; }
    .feature-list li::before { content: "✓"; display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px; background: var(--primary); color: white; border-radius: 50%; font-size: 12px; flex-shrink: 0; }

    /* Video Editor */
    .video-editor { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
    .video-editor-visual { background: linear-gradient(135deg, #292A2E 0%, #374151 100%); border-radius: var(--radius); padding: 60px; min-height: 300px; display: flex; align-items: center; justify-content: center; color: white; font-size: 48px; }

    /* Integrations */
    .integrations-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
    .integration-card { background: white; border: 1px solid var(--border); border-radius: var(--radius); padding: 32px; text-align: center; transition: all 0.2s; }
    .integration-card:hover { border-color: var(--primary); box-shadow: var(--shadow); transform: translateY(-2px); }
    .integration-card-icon { width: 48px; height: 48px; margin: 0 auto 16px; background: var(--bg-alt); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; font-size: 24px; }

    /* Engagement */
    .engagement-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
    .engagement-card { background: white; border: 1px solid var(--border); border-radius: var(--radius); padding: 32px; }
    .engagement-card h3 { font-size: 20px; font-weight: 700; margin-bottom: 12px; }
    .engagement-card p { color: var(--text-light); font-size: 15px; }

    /* Security */
    .security-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
    .security-card { background: var(--bg-secondary); border-radius: var(--radius); padding: 28px; text-align: center; }
    .security-card-icon { width: 56px; height: 56px; margin: 0 auto 16px; background: linear-gradient(135deg, var(--primary) 0%, var(--purple) 100%); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 24px; }
    .security-card h3 { font-size: 16px; font-weight: 700; margin-bottom: 8px; }
    .security-card p { color: var(--text-light); font-size: 14px; }

    /* Use Cases */
    .use-cases-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
    .use-case-card { background: white; border: 1px solid var(--border); border-radius: var(--radius); padding: 32px; text-align: center; transition: all 0.2s; cursor: pointer; }
    .use-case-card:hover { border-color: var(--primary); box-shadow: var(--shadow); transform: translateY(-2px); }
    .use-case-icon { width: 64px; height: 64px; margin: 0 auto 20px; background: linear-gradient(135deg, #EFF6FF 0%, #E0E7FF 100%); border-radius: var(--radius); display: flex; align-items: center; justify-content: center; font-size: 28px; }
    .use-case-card h3 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
    .use-case-card p { color: var(--text-light); font-size: 14px; }

    /* Features Grid */
    .features-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
    .feature-card { background: var(--bg-secondary); border-radius: var(--radius); padding: 28px; display: flex; gap: 16px; }
    .feature-icon { width: 44px; height: 44px; background: linear-gradient(135deg, var(--primary) 0%, var(--purple) 100%); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; color: white; font-size: 20px; flex-shrink: 0; }
    .feature-card h3 { font-size: 16px; font-weight: 700; margin-bottom: 6px; }
    .feature-card p { color: var(--text-light); font-size: 14px; }

    /* Blog */
    .blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; }
    .blog-card { background: white; border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; transition: all 0.2s; }
    .blog-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
    .blog-image { height: 200px; background: linear-gradient(135deg, var(--primary) 0%, var(--purple) 100%); display: flex; align-items: center; justify-content: center; color: white; font-size: 48px; }
    .blog-content { padding: 24px; }
    .blog-content h3 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
    .blog-content p { color: var(--text-light); font-size: 14px; margin-bottom: 16px; }

    /* Enterprise CTA */
    .enterprise-cta { background: linear-gradient(135deg, #292A2E 0%, #374151 100%); color: white; text-align: center; border-radius: var(--radius); padding: 60px; }
    .enterprise-cta h2 { font-size: 32px; font-weight: 700; margin-bottom: 12px; }
    .enterprise-cta p { color: rgba(255,255,255,0.8); font-size: 18px; margin-bottom: 24px; }

    /* Testimonials */
    .testimonials-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
    .testimonial-card { background: white; border: 1px solid var(--border); border-radius: var(--radius); padding: 28px; }
    .testimonial-card p { font-size: 15px; margin-bottom: 16px; color: var(--text); line-height: 1.7; }
    .testimonial-author { display: flex; align-items: center; gap: 12px; }
    .testimonial-avatar { width: 40px; height: 40px; background: linear-gradient(135deg, var(--primary) 0%, var(--purple) 100%); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-weight: 700; font-size: 16px; }
    .testimonial-name { font-weight: 600; font-size: 14px; }
    .testimonial-role { color: var(--text-light); font-size: 13px; }

    /* CTA Banner */
    .cta-banner { background: linear-gradient(135deg, var(--primary) 0%, var(--purple) 100%); color: white; text-align: center; padding: 60px 24px; border-radius: var(--radius); }
    .cta-banner h2 { font-size: 36px; font-weight: 800; margin-bottom: 8px; }
    .cta-banner p { font-size: 18px; opacity: 0.9; margin-bottom: 24px; }

    /* Footer */
    .footer { background: var(--text); color: white; padding: 60px 0 30px; }
    .footer-grid { display: grid; grid-template-columns: 2fr repeat(5, 1fr); gap: 40px; margin-bottom: 40px; }
    .footer-brand p { color: rgba(255,255,255,0.6); font-size: 14px; margin-top: 12px; max-width: 280px; }
    .footer-col h4 { font-size: 14px; font-weight: 700; margin-bottom: 16px; text-transform: uppercase; letter-spacing: 0.5px; }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 10px; }
    .footer-col a { color: rgba(255,255,255,0.6); font-size: 14px; transition: color 0.2s; }
    .footer-col a:hover { color: white; }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 30px; display: flex; justify-content: space-between; align-items: center; }
    .footer-bottom p { color: rgba(255,255,255,0.5); font-size: 13px; }

    /* Cookie Banner */
    .cookie-banner { position: fixed; bottom: 0; left: 0; right: 0; background: white; border-top: 1px solid var(--border); padding: 20px 24px; box-shadow: 0 -4px 20px rgba(0,0,0,0.1); z-index: 1000; display: none; }
    .cookie-banner.show { display: block; }
    .cookie-inner { max-width: 1200px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; }
    .cookie-text { font-size: 14px; color: var(--text); }
    .cookie-actions { display: flex; gap: 12px; }
    .cookie-link { color: var(--primary); font-size: 14px; cursor: pointer; text-decoration: underline; }

    /* Cookie Modal */
    .cookie-modal { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5); z-index: 1001; display: none; align-items: center; justify-content: center; }
    .cookie-modal.show { display: flex; }
    .cookie-modal-content { background: white; border-radius: var(--radius); padding: 32px; max-width: 500px; width: 90%; max-height: 80vh; overflow-y: auto; }
    .cookie-modal h3 { font-size: 20px; font-weight: 700; margin-bottom: 16px; }
    .cookie-category { padding: 16px 0; border-bottom: 1px solid var(--border); }
    .cookie-category:last-child { border-bottom: none; }
    .cookie-category-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
    .cookie-category h4 { font-size: 15px; font-weight: 600; }
    .cookie-category p { font-size: 13px; color: var(--text-light); }
    .toggle-switch { width: 44px; height: 24px; background: var(--border); border-radius: 12px; position: relative; cursor: pointer; transition: background 0.2s; }
    .toggle-switch.active { background: var(--primary); }
    .toggle-switch::after { content: ""; position: absolute; width: 20px; height: 20px; background: white; border-radius: 50%; top: 2px; left: 2px; transition: transform 0.2s; }
    .toggle-switch.active::after { transform: translateX(20px); }
    .cookie-modal-actions { display: flex; gap: 12px; margin-top: 24px; }

    /* Responsive */
    @media (max-width: 768px) {
      .nav-links { display: none; }
      .feature-highlight, .screen-recorder, .video-editor { grid-template-columns: 1fr; }
      .integrations-grid { grid-template-columns: repeat(2, 1fr); }
      .engagement-grid, .testimonials-grid { grid-template-columns: 1fr; }
      .security-grid, .use-cases-grid { grid-template-columns: repeat(2, 1fr); }
      .features-grid { grid-template-columns: 1fr; }
      .blog-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
    }
  </style>
</head>
